<script setup>
import { computed, onMounted, ref } from 'vue';
import { ArrowLeft, CheckCircle2, FileUp, LoaderCircle } from 'lucide-vue-next';
import { useRouter } from 'vue-router';
import { useAlonaAuthStore } from '../../stores/alonaAuthStore';
import { calculateAge } from '../../utils/psgc';
const router = useRouter(); const store = useAlonaAuthStore();
const form = ref({ first_name: '', last_name: '', middle_initial: '', sex: '', email: '', phone_number: '', birthdate: '', province: '', city_municipality: '', barangay: '', street_address: '', business_name: '', password: '', password_confirmation: '' });
const idFile = ref(null); const permitFile = ref(null); const idPreview = ref(''); const submitted = ref(false); const error = ref(''); const age = computed(() => calculateAge(form.value.birthdate));
const setFile = (target, event) => { const file = event.target.files?.[0]; if (!file) return; target.value = file; };
const loadMunicipalities = (event) => store.loadMunicipalities(store.provinces.find((province) => province.code === event.target.value));
const loadBarangays = (event) => store.loadBarangays(store.municipalities.find((municipality) => municipality.code === event.target.value));
const submit = async () => { error.value = ''; if (!age.value || age.value < 18) { error.value = 'Applicants must be at least 18 years old.'; return; } const data = new FormData(); data.append('account_type', 'logistics'); Object.entries(form.value).forEach(([key, value]) => data.append(key, value)); data.append('id_document', idFile.value); data.append('business_permit', permitFile.value); try { await store.registerStaff(data); submitted.value = true; } catch (requestError) { error.value = requestError.message; } };
onMounted(() => store.loadAllProvinces());
</script>
<template>
  <main class="min-h-screen bg-[#f3f7f6] px-4 py-8 text-slate-900 sm:px-6"><section class="mx-auto max-w-4xl"><button class="inline-flex items-center gap-2 text-sm font-bold text-teal-700" @click="router.push('/auth/register-role')"><ArrowLeft class="h-4 w-4" />Account type</button><div v-if="submitted" class="mt-8 border border-emerald-200 bg-white p-8 shadow-sm"><CheckCircle2 class="h-10 w-10 text-emerald-600" /><h1 class="mt-5 text-3xl font-black">Registration submitted</h1><p class="mt-3 text-slate-600">After submitting your registration, please wait for the administrator's approval, which will be sent to your email.</p></div><form v-else class="mt-8 border border-slate-200 bg-white p-6 shadow-sm sm:p-8" @submit.prevent="submit"><p class="text-xs font-black uppercase tracking-[0.2em] text-blue-700">Logistics / Sorting Center</p><h1 class="mt-2 text-3xl font-black">Register as staff</h1><div class="mt-8 grid gap-4 sm:grid-cols-3"><label>Last name*<input v-model="form.last_name" required class="field" /></label><label>First name*<input v-model="form.first_name" required class="field" /></label><label>Middle initial<input v-model="form.middle_initial" maxlength="2" class="field" /></label><label>Sex*<select v-model="form.sex" required class="field"><option value="">Select</option><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></label><label>E-mail*<input v-model="form.email" required type="email" class="field" /></label><label>Contact No.*<input v-model="form.phone_number" required pattern="[0-9]{11}" maxlength="11" placeholder="09171234567" class="field" /></label><label>Birthday*<input v-model="form.birthdate" required type="date" class="field" /></label><label>Age (autogen)*<input :value="age || ''" readonly class="field bg-slate-100" /></label><label>Business name<input v-model="form.business_name" class="field" /></label></div><div class="mt-6 grid gap-4 sm:grid-cols-3"><label>Province*<select v-model="form.province" required class="field" @change="loadMunicipalities"><option value="">Select province</option><option v-for="province in store.provinces" :key="province.code" :value="province.name">{{ province.name }}</option></select></label><label>Municipality*<select v-model="form.city_municipality" required class="field" @change="loadBarangays"><option value="">Select municipality</option><option v-for="municipality in store.municipalities" :key="municipality.code" :value="municipality.name">{{ municipality.name }}</option></select></label><label>Barangay*<select v-model="form.barangay" required class="field"><option value="">Select barangay</option><option v-for="barangay in store.barangays" :key="barangay.code" :value="barangay.name">{{ barangay.name }}</option></select></label></div><label class="mt-4 block">Street, house number, building / landmark*<input v-model="form.street_address" required class="field" /></label><div class="mt-6 grid gap-4 sm:grid-cols-2"><label class="border border-dashed border-slate-300 p-4"><span class="flex items-center gap-2 font-bold"><FileUp class="h-4 w-4 text-blue-700" />Upload Valid ID*</span><input required type="file" accept="image/*,.pdf" class="mt-3 block w-full text-sm" @change="setFile(idFile, $event)" /></label><label class="border border-dashed border-slate-300 p-4"><span class="flex items-center gap-2 font-bold"><FileUp class="h-4 w-4 text-blue-700" />Upload Business / DTI Permit*</span><input required type="file" accept="image/*,.pdf" class="mt-3 block w-full text-sm" @change="setFile(permitFile, $event)" /></label></div><div class="mt-6 grid gap-4 sm:grid-cols-2"><label>Password*<input v-model="form.password" required minlength="8" type="password" class="field" /></label><label>Confirm password*<input v-model="form.password_confirmation" required type="password" class="field" /></label></div><p v-if="error" class="mt-5 border border-rose-200 bg-rose-50 p-3 text-sm text-rose-700">{{ error }}</p><div class="mt-6 border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">After submitting your registration, please wait for the administrator's approval, which will be sent to your email.</div><button :disabled="store.loading" class="mt-5 inline-flex items-center gap-2 bg-slate-950 px-5 py-3 text-sm font-black text-white disabled:opacity-50"><LoaderCircle v-if="store.loading" class="h-4 w-4 animate-spin" />Submit staff application</button></form></section></main>
</template>
<style scoped>.field{margin-top:.375rem;width:100%;border:1px solid #cbd5e1;padding:.65rem .75rem;font-size:.875rem;background:white}</style>
